package main
import("context";"fmt";"os";"path/filepath";"time";"github.com/daydemir/stoarama/backend/internal/capture";"github.com/jackc/pgx/v5/pgxpool")
func main(){c:=context.Background();p,e:=pgxpool.New(c,os.Getenv("DATABASE_URL"));if e!=nil{panic(e)};defer p.Close();for _,id:=range []int64{411,412,432,434,435}{var provider,cat,page string;if e:=p.QueryRow(c,`select s.provider,s.source_url,coalesce(s.source_page_url,'') from recordings r join streams s on s.id=r.stream_id where r.id=$1 and r.account_id=47`,id).Scan(&provider,&cat,&page);e!=nil{fmt.Printf("PROBE %d catalog_error=%v\n",id,e);continue};pc,cancel:=context.WithTimeout(c,35*time.Second);resolved,image,headers,e:=capture.ResolveCaptureInputWithHeaders(pc,provider,cat,page);if e!=nil{fmt.Printf("PROBE %d resolved=false image=%t error=%q\n",id,image,e.Error());cancel();continue};seg,ce:=capture.CaptureSegmentInDirWithHeadersNoThumbnail(pc,resolved,15*time.Second,"","",headers);if seg.Path!=""{_ = os.RemoveAll(filepath.Dir(seg.Path))};if ce!=nil{fmt.Printf("PROBE %d resolved=true decode_ok=false duration_ms=%d bytes=%d error=%q\n",id,seg.DurationMs,seg.SizeBytes,ce.Error())}else{fmt.Printf("PROBE %d resolved=true decode_ok=true duration_ms=%d bytes=%d codec=%s\n",id,seg.DurationMs,seg.SizeBytes,seg.VideoCodec)};cancel()}}
